UPDATE companies SET description='Grimm observed that the original values of his former business—and of the broader automotive aftermarket—were eroding under corporate ownership, so he started OVERTAKE to restore community-focused craftsmanship for Subaru enthusiasts.

The company designs and manufactures a range of aftermarket performance parts for Subaru models including the WRX, STI, Forester XT, BRZ/86, Crosstrek, and others. Its product line covers transmission mount inserts, post-MAF pipe kits, top-mount intercoolers, DAVCS cam solenoid heat shields, and gasket sets. OVERTAKE emphasizes engineered products at accessible price points and involves its community in product development through a dedicated Facebook group.

OVERTAKE serves the automotive aftermarket, specifically Subaru performance enthusiasts and retail customers, and also supports a dealer network. The company offers a 10% hero discount to military personnel, teachers, and healthcare workers, and provides free shipping on most orders over $250 within the lower 48 states.

Grimm started OVERTAKE to rebuild what he saw as lost values—passion, quality, and community engagement. The company differentiates itself with same-day shipping on orders placed by 2 PM CST, a 30-day hassle-free return policy, and a crowd-sourced design process that aims to over-deliver on community feedback.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Aftermarket performance parts manufacturing", "Product design and engineering", "Same-day order fulfillment", "Customer service and support", "Community-driven product development"], "industries": ["Automotive aftermarket", "Subaru performance parts"], "materials": [], "equipment": [], "volume": "", "lead_time": "Same-day shipping on orders placed by 2\u202fPM CST", "tolerances": "", "built_on": ["Same-day shipping on orders placed by 2\u202fPM CST", "Crowd-sourced product development via community feedback", "Engineered performance parts at accessible pricing", "30-day hassle-free return policy", "Hero discounts for military, teachers, and healthcare workers"], "facts_used": ["Founded in 2019 by Justin Grimm -> db", "Headquartered in St Paul, Minnesota -> db", "Aftermarket parts manufacturer for Subaru vehicles -> /", "20 years of Subaru-focused dedication -> /", "Same-day shipping on orders by 2pm CST -> /", "Hero discounts for military, teachers, healthcare -> /", "30-day return policy -> /", "Crowd-sourced product development via Facebook group -> /", "Free shipping on orders over $250 -> /", "Products include transmission mount inserts, post MAF pipe kits, top mount intercoolers, DAVCS cam solenoid heat shields -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "As an aftermarket parts manufacturer, we believe it''s our responsibility to be caretakers of this unique community", "founded_year": "2019", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='overtake' AND approved AND profile IS NULL;
UPDATE companies SET description='OakTree Supply has operated in Fort Wayne, Indiana since 1998, when it opened as a family-owned brick-and-mortar store serving the local woodworking community. In 2014 new ownership took over, expanding the business into online retail and broadening the product assortment to become a dedicated resource for serious woodworkers.

The company stocks a wide range of woodworking machinery, power tools, hand tools, CNC accessories, dust collection systems, and finishing supplies from brands such as Festool, SawStop, Laguna, Lamello, SCM, and BOW Products. An industrial machinery specialist, Logan, provides consultation for businesses adding or upgrading equipment, and the company offers financing options for machinery purchases.

Customers include hobbyist woodworkers, professional cabinet and furniture shops, and businesses seeking to increase productivity with new machinery. The retailer serves both individual craftsmen and commercial operations across the woodworking sector.

OakTree Supply emphasizes its identity as a family-owned small business that personally tests every product it carries, promising that staff will not sell items they would not use in their own shops. It also highlights live-person customer service without automated attendants and regular in-store demo events covering turning, epoxy pouring, and finishing techniques.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Retail sales of woodworking machinery and tools", "Product selection consulting", "Machinery financing facilitation", "In-store product demonstrations", "Online and brick-and-mortar sales"], "industries": ["Woodworking", "Cabinet making", "Furniture manufacturing", "Professional woodworking shops"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Family-owned small business that tests every product before sale", "Live-person customer service with no automated phone system", "Dedicated industrial machinery specialist for equipment consultation", "Business financing available for machinery purchases", "Free shipping on orders over $45 and regular hands-on demo events"], "facts_used": ["Founded 1998, family-owned, Fort Wayne, Indiana -> db", "New ownership in 2014 expanded to online retail -> db", "Sells woodworking machinery, tools, supplies from brands like Festool, SawStop, Laguna, Lamello, SCM, BOW Products -> /", "Industrial machinery specialist Logan provides consultation -> /", "Offers financing for machinery purchases -> /", "Serves hobbyists, professional cabinet/furniture shops, businesses -> /", "Emphasizes product testing, live-person service, demo events -> /"], "company_type": "Retailer", "makes_products": "no", "type_evidence": "Family owned and operated since 1998, OakTree Supply started out with a single brick and mortar store serving the local Fort Wayne, Indiana woodworking community... expanded into the online retail space", "founded_year": "1998", "employee_count": "", "cage_co